//! `request` (src/models/request/) against the database: scoping, ordering, paging.
//! Generated by `cargo offrails generate resource requests agent:references{agent} title:string description:text category:string location:string budget:money`.

use board::error::AppError;
use board::models::{Page, request};

use crate::factories;
use crate::support::TestApp;

#[tokio::test]
async fn find_for_sees_only_the_owners_requests() {
    let app = TestApp::new().await;
    let alice = factories::user(app.db(), "alice@example.com").await;
    let bob = factories::user(app.db(), "bob@example.com").await;
    let record = factories::request(app.db(), &alice).await;
    assert_eq!(
        request::find_for(app.db(), &alice, record.id)
            .await
            .unwrap(),
        record
    );
    assert!(matches!(
        request::find_for(app.db(), &bob, record.id).await,
        Err(AppError::NotFound)
    ));
    assert!(matches!(
        request::destroy_for(app.db(), &bob, record.clone()).await,
        Err(AppError::NotFound)
    ));
    assert!(
        factories::reload_request(app.db(), record.id)
            .await
            .is_some()
    );
}

#[tokio::test]
async fn all_for_pages_newest_first() {
    let app = TestApp::new().await;
    let alice = factories::user(app.db(), "alice@example.com").await;
    let bob = factories::user(app.db(), "bob@example.com").await;
    let first = factories::request(app.db(), &alice).await;
    let second = factories::request(app.db(), &alice).await;
    let third = factories::request(app.db(), &alice).await;
    factories::request(app.db(), &bob).await;
    let (rows, more) = request::all_for(app.db(), &alice, Page::new(1, 2))
        .await
        .unwrap();
    assert_eq!(rows, vec![third, second]);
    assert!(more);
    let (rows, more) = request::all_for(app.db(), &alice, Page::new(2, 2))
        .await
        .unwrap();
    assert_eq!(rows, vec![first]);
    assert!(!more);
}

#[tokio::test]
async fn update_for_and_destroy_for_change_the_owners_request() {
    let app = TestApp::new().await;
    let alice = factories::user(app.db(), "alice@example.com").await;
    let record = factories::request(app.db(), &alice).await;
    let params = factories::request_params(app.db(), &alice).await;
    let new = params.validate().unwrap();
    let updated = request::update_for(app.db(), &alice, record.clone(), new)
        .await
        .unwrap();
    assert_eq!(updated.id, record.id);
    assert!(updated.updated_at >= record.updated_at);
    request::destroy_for(app.db(), &alice, updated)
        .await
        .unwrap();
    assert_eq!(
        factories::reload_request(app.db(), record.id)
            .await
            .unwrap()
            .status,
        request::RequestStatus::Cancelled
    );
}

/// The edit form shows what was saved: params from a record validate back to it.
#[tokio::test]
async fn the_edit_form_round_trips_a_saved_request() {
    let app = TestApp::new().await;
    let alice = factories::user(app.db(), "alice@example.com").await;
    let record = factories::request(app.db(), &alice).await;
    let new = request::RequestParams::from(&record).validate().unwrap();
    let saved = request::update_for(app.db(), &alice, record.clone(), new)
        .await
        .unwrap();
    assert_eq!(
        request::Model {
            updated_at: record.updated_at,
            ..saved
        },
        record
    );
}

/// A agent the user can't see can't be referenced (it looks missing).
#[tokio::test]
async fn another_users_agent_cant_be_referenced() {
    let app = TestApp::new().await;
    let alice = factories::user(app.db(), "alice@example.com").await;
    let bob = factories::user(app.db(), "bob@example.com").await;
    let theirs = factories::agent(app.db(), &bob).await;
    let mut params = factories::request_params(app.db(), &alice).await;
    params.agent_id = theirs.id.to_string();
    let new = params.validate().unwrap();
    match request::create(app.db(), &alice, new).await {
        Err(AppError::Invalid(errors)) => assert_eq!(errors.on("agent"), ["must exist"]),
        other => panic!("expected a validation error, got {other:?}"),
    }
}
